"""Unique Paths — one DP row rolled across the grid.

(The closed form C(m+n-2, m-1) also works; the row keeps the DP shape visible.)

Time: O(m*n)   Space: O(n)
"""


class Solution:
    def uniquePaths(self, m: int, n: int) -> int:
        row = [1] * n
        for _ in range(m - 1):
            for j in range(1, n):
                row[j] += row[j - 1]
        return row[-1]
